parse_multimodel_response &lt;- function(path, model_name) {
  tryCatch({
    r &lt;- jsonlite::fromJSON(path, simplifyVector = FALSE)
    paper &lt;- basename(path) |&gt;
      str_replace("\\.response\\.json$", "") |&gt;
      str_replace_all("_", " ")

    # Parse the output_text JSON
    if (!is.null(r$output_text) && nchar(r$output_text) &gt; 0) {
      parsed &lt;- jsonlite::fromJSON(r$output_text, simplifyVector = TRUE)
      metrics &lt;- parsed$metrics

      # Extract percentile metrics
      metric_rows &lt;- list()
      tier_rows &lt;- list()

      for (nm in names(metrics)) {
        if (nm %in% c("tier_should", "tier_will")) {
          tier_rows[[length(tier_rows) + 1]] &lt;- tibble(
            paper = paper,
            model = model_name,
            tier_kind = nm,
            score = metrics[[nm]]$score,
            ci_lower = metrics[[nm]]$ci_lower,
            ci_upper = metrics[[nm]]$ci_upper
          )
        } else {
          metric_rows[[length(metric_rows) + 1]] &lt;- tibble(
            paper = paper,
            model = model_name,
            metric = nm,
            midpoint = metrics[[nm]]$midpoint,
            lower_bound = metrics[[nm]]$lower_bound,
            upper_bound = metrics[[nm]]$upper_bound
          )
        }
      }

      list(
        metrics = bind_rows(metric_rows),
        tiers = bind_rows(tier_rows),
        summary = tibble(
          paper = paper,
          model = model_name,
          assessment_summary = parsed$assessment_summary,
          input_tokens = r$usage$input_tokens,
          output_tokens = r$usage$output_tokens
        )
      )
    } else {
      # Try parsing from "parsed" field (Anthropic/Google format)
      if (!is.null(r$parsed)) {
        metrics &lt;- r$parsed$metrics
        metric_rows &lt;- list()
        tier_rows &lt;- list()

        for (nm in names(metrics)) {
          if (nm %in% c("tier_should", "tier_will")) {
            tier_rows[[length(tier_rows) + 1]] &lt;- tibble(
              paper = paper,
              model = model_name,
              tier_kind = nm,
              score = metrics[[nm]]$score,
              ci_lower = metrics[[nm]]$ci_lower,
              ci_upper = metrics[[nm]]$ci_upper
            )
          } else {
            metric_rows[[length(metric_rows) + 1]] &lt;- tibble(
              paper = paper,
              model = model_name,
              metric = nm,
              midpoint = metrics[[nm]]$midpoint,
              lower_bound = metrics[[nm]]$lower_bound,
              upper_bound = metrics[[nm]]$upper_bound
            )
          }
        }

        list(
          metrics = bind_rows(metric_rows),
          tiers = bind_rows(tier_rows),
          summary = tibble(
            paper = paper,
            model = model_name,
            assessment_summary = r$parsed$assessment_summary,
            input_tokens = r$input_tokens,
            output_tokens = r$output_tokens
          )
        )
      } else {
        NULL
      }
    }
  }, error = function(e) {
    message(sprintf("Error parsing %s: %s", path, e$message))
    NULL
  })
}

