Show code
# Pricing per 1M tokens (USD) - as of late 2024
pricing &lt;- tribble(
  ~model,              ~input_per_m, ~output_per_m,
  "GPT-4o-mini",       0.15,         0.60,
  "Claude Sonnet 4",   3.00,         15.00,
  "Gemini 2.0 Flash",  0.075,        0.30,
  "GPT-5 Pro",         15.00,        60.00
)

# Extract token usage from all JSON files
extract_tokens &lt;- function() {
  all_tokens &lt;- list()

  for (dir_name in names(model_dirs)) {
    model_name &lt;- model_dirs[[dir_name]]
    json_dir &lt;- here("results", dir_name, "json")

    if (dir.exists(json_dir)) {
      files &lt;- list.files(json_dir, pattern = "\\.response\\.json$", full.names = TRUE)

      for (f in files) {
        tryCatch({
          r &lt;- jsonlite::fromJSON(f, simplifyVector = FALSE)
          paper &lt;- basename(f) |&gt;
            str_replace("\\.response\\.json$", "") |&gt;
            str_replace_all("_", " ")

          # Handle different JSON structures
          if (!is.null(r$usage)) {
            # OpenAI format
            input_tok &lt;- r$usage$input_tokens
            output_tok &lt;- r$usage$output_tokens
          } else {
            # Anthropic/Gemini format
            input_tok &lt;- r$input_tokens
            output_tok &lt;- r$output_tokens
          }

          all_tokens[[length(all_tokens) + 1]] &lt;- tibble(
            paper = paper,
            model = model_name,
            input_tokens = input_tok %||% NA_integer_,
            output_tokens = output_tok %||% NA_integer_
          )
        }, error = function(e) NULL)
      }
    }
  }

  bind_rows(all_tokens)
}

token_data &lt;- extract_tokens()

if (nrow(token_data) &gt; 0) {

  # Calculate costs
  token_summary &lt;- token_data |&gt;
    left_join(pricing, by = "model") |&gt;
    mutate(
      total_tokens = input_tokens + output_tokens,
      cost_usd = (input_tokens * input_per_m + output_tokens * output_per_m) / 1e6
    ) |&gt;
    group_by(model) |&gt;
    summarise(
      `Papers` = n(),
      `Avg input tokens` = round(mean(input_tokens, na.rm = TRUE)),
      `Avg output tokens` = round(mean(output_tokens, na.rm = TRUE)),
      `Total tokens` = sum(total_tokens, na.rm = TRUE),
      `Total cost (USD)` = round(sum(cost_usd, na.rm = TRUE), 3),
      `Avg cost/paper` = round(mean(cost_usd, na.rm = TRUE), 4),
      .groups = "drop"
    ) |&gt;
    arrange(desc(`Total cost (USD)`))

  knitr::kable(token_summary,
               align = c("l", rep("r", 6)),
               format.args = list(big.mark = ","))
} else {
  cat("No token data available.\n")
}




